import { useMemo, useState } from 'react'
import { useHistory } from 'react-router'
import { ARROW_RIGHT_WHITE, EDIT_BLUE, RELOAD_RED, WALLET_PURPLE } from '../../../../../images'
import useEventTracker from '../../../../../hooks/trackers'
import { checkIsLvAgent } from '../../../../../helpers/checkAgentTags'
import PopupDraftList from '../../../Policy/pages/TransactionList/container/components/PopupDraftList'
import PopupPaymentPending from '../../../Policy/pages/TransactionList/container/components/PopupPaymentPending'
import AgentBadge from '../AgentBadge'
import {
  TopSectionStyle,
  NotificationSummary,
  ActionCardContainer,
  ActionCard,
} from './index.style'

const ACTIONS = {
  RENEWAL: 'RENEWAL',
  PAYMENT: 'PAYMENT',
  DRAFT: 'DRAFT',
}

const formatCount = (count) => {
  if (!count && count !== 0) return '-'
  if (count === 0) return '0'
  if (count > 99) return '99+'
  return count
}

function DashboardTopSection(props) {
  const { isHideAgentBadges, getAgentDetailData, getTransactionSummaryData } = props

  const history = useHistory()
  const [showPopup, setShowPopup] = useState(null)
  const { trackUserEvent } = useEventTracker()

  const actionCards = useMemo(() => {
    const actions = [
      {
        key: ACTIONS.RENEWAL,
        label: 'Perpanjang Polis',
        count: getTransactionSummaryData.renewable_records?.all,
        icon: RELOAD_RED,
        onClick: () => {
          trackUserEvent('[MV Renewal] View Renewal List Page', {
            source: 'Home Page - Summary',
            renewal_count: getTransactionSummaryData?.renewable_records?.all,
          })
          history.push('/renewals/list')
        },
      },
      {
        key: ACTIONS.PAYMENT,
        label: 'Menunggu Pembayaran',
        count: getTransactionSummaryData.unpaid_records,
        icon: WALLET_PURPLE,
        onClick: () => setShowPopup(ACTIONS.PAYMENT),
      },
      {
        key: ACTIONS.DRAFT,
        label: 'Selesaikan Pengajuan',
        count: getTransactionSummaryData.action_pending_records,
        icon: EDIT_BLUE,
        onClick: () => setShowPopup(ACTIONS.DRAFT),
      },
    ]
    const isLvAgent = checkIsLvAgent(getAgentDetailData)
    if (!isLvAgent) {
     return actions.slice(1, 2)
    }
    return actions
  }, [history, getAgentDetailData, getTransactionSummaryData, trackUserEvent])

  return (
    <TopSectionStyle>
      {isHideAgentBadges !== true && (
        <AgentBadge
          isNotificationCount={!!getAgentDetailData.notification_unread_count}
          agentCode={getAgentDetailData?.agent_code}
        />
      )}
      {!!getAgentDetailData.notification_unread_count && (
        <NotificationSummary
          role="button"
          tabIndex={0}
          onClick={() => history.push('/notifications')}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') history.push('/notifications')
          }}
          data-gtm-element-id="notifications"
          data-gtm-entry="Dashboard Active"
        >
          <div className="notification-summary-left">
            <div className="notification-summary-count">
              {formatCount(getAgentDetailData.notification_unread_count)}
            </div>
            <div className="notification-summary-text">Tugas perlu diselesaikan</div>
          </div>
          <div className="notification-summary-right">
            <img src={ARROW_RIGHT_WHITE} alt="Next" />
          </div>
        </NotificationSummary>
      )}

      <ActionCardContainer>
        {actionCards.map((card) => (
          <ActionCard
            key={card.key}
            role="button"
            tabIndex={0}
            onClick={card.onClick}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') card.onClick()
            }}
          >
            <div className="action-card-top">
              <div className={`action-card-count ${card.key}`}>{formatCount(card.count)}</div>
              <img className="action-icon" src={card.icon} alt="" />
            </div>
            <div className="action-card-label">{card.label}</div>
          </ActionCard>
        ))}
      </ActionCardContainer>

      <PopupPaymentPending
        show={showPopup === ACTIONS.PAYMENT}
        onClose={() => setShowPopup(null)}
      />
      <PopupDraftList show={showPopup === ACTIONS.DRAFT} onClose={() => setShowPopup(null)} />
    </TopSectionStyle>
  )
}

export default DashboardTopSection
