import { useCallback, useState } from 'react'
import Cookies from 'universal-cookie'
import moment from 'moment'
import { Button, CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { SHOW_DOWN_TIME } from '../../../../../constants/cookies'
import { showDownTimeNotification } from '../../../../../helpers/utility'
import { DOWNTIME_MSG, LANG_STRINGS } from '../../../../../lang'
import { DownTimeNotificationStyle } from './index.style'
import BottomActionSheet from '../../../../../components/BottomActionSheet'

const cookies = new Cookies()

function DownTimeNotification () {
  const [showDownTime, setShowDownTime] = useState(showDownTimeNotification() && !cookies.get(SHOW_DOWN_TIME))

  const handleDownTimeNote = useCallback(() => {
    // here we are handling the down time note
    setShowDownTime(false)
    cookies.set(SHOW_DOWN_TIME, 'false', {
      path: '/',
      expires: new Date(moment().add(6, 'h').format())
    })
  }, [])

  return showDownTime ? (
    <BottomActionSheet
      title={LANG_STRINGS.systemMaintenance}
      onCloseSheet={handleDownTimeNote}
      showHeader
      show={showDownTime}
    >
      <DownTimeNotificationStyle>
        <CustomText
          color={AgentColorPallette.darkCharcoal}
          size='1em'
          bottom='1rem'
        >
          {DOWNTIME_MSG}
        </CustomText>
        <Button onClick={handleDownTimeNote}>
          {LANG_STRINGS.okay}
        </Button>
      </DownTimeNotificationStyle>
    </BottomActionSheet>
  ) : null
}

export default DownTimeNotification
