import {
  CAR_PROTECTION,
  EXTENDED_WARRANTY_PROTECTION,
  PROPERTY_PROTECTION,
  TRAVEL_PROTECTION,
} from '../../../../../../../../constants/pkgCode'
import {
  useDraftPrevSteps,
  useDraftPrevStepsExtendedWarranty,
  useDraftPrevStepsPropertyProtection,
  useDraftPrevStepsTravel,
} from '../../../../../../../../state/commonState/hooks/useDraftPrevSteps'

function useContinueDraft() {
  const draftPrevSteps = useDraftPrevSteps()
  const draftPrevStepsExtendedWarranty = useDraftPrevStepsExtendedWarranty()
  const draftPrevStepsPropertyProtection = useDraftPrevStepsPropertyProtection()
  const draftPrevStepsTravel = useDraftPrevStepsTravel()

  const handleContinueDraft = (draftData) => {
    switch (draftData?.product_code) {
      case CAR_PROTECTION:
        draftPrevSteps({
          section: draftData.section,
          subSection: draftData.sub_section,
          id: draftData.id,
        })
        break
      case EXTENDED_WARRANTY_PROTECTION:
        draftPrevStepsExtendedWarranty({
          section: draftData.section,
          subSection: draftData.sub_section,
          id: draftData.id,
        })
        break
      case PROPERTY_PROTECTION:
        draftPrevStepsPropertyProtection({
          section: draftData.section,
          subSection: draftData.sub_section,
          id: draftData.id,
          packageCode: draftData.provider_package_code,
        })
        break
      case TRAVEL_PROTECTION:
        draftPrevStepsTravel({
          section: draftData.section,
          subSection: draftData.sub_section,
          id: draftData.id,
        })
        break
      default:
        break
    }
  }

  return { handleContinueDraft }
}

export default useContinueDraft
