import { Component } from 'react'
import PropTypes from 'prop-types'
import FullPageModal from '../../../../../components/FullPageModal'
import { PromoDetailModalStyle } from './index.style'
import { FlatBottomBtn } from '../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../lang'

class PromoBannerDetailModal extends Component {
  static propTypes = {
    imgUrl: PropTypes.string,
    title: PropTypes.string,
    showModal: PropTypes.bool,
    showBtn: PropTypes.bool,
    onReferralBtnClick: PropTypes.func,
    onCloseModal: PropTypes.func,
  }

  render() {
    const { imgUrl, title, showModal, showBtn, onReferralBtnClick, onCloseModal } = this.props
    return (
      <FullPageModal onCloseModal={onCloseModal} showModal={showModal} isImgHeader>
        <PromoDetailModalStyle paddingBtm={showBtn}>
          <img src={imgUrl} alt={title} />
        </PromoDetailModalStyle>
        {showBtn && (
          <FlatBottomBtn onClick={onReferralBtnClick}>{LANG_STRINGS.referNow}</FlatBottomBtn>
        )}
      </FullPageModal>
    )
  }
}

export default PromoBannerDetailModal
