import { useCallback, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import BottomActionSheet from '../../../../../../../../components/BottomActionSheet'
import CircularLoader from '../../../../../../../../components/CircularLoader'
import CustomCheckbox from '../../../../../../../../components/CustomCheckbox'
import LazyLoader from '../../../../../../../../components/LazyLoader'
import ShowSnackbar from '../../../../../../../../components/ShowNotification'
import { AgentColorPallette } from '../../../../../../../../configs/colorPallete'
import { useGetPolicyDraftList, useSetPolicyState } from '../../../../../state/hooks/usePolicyState'
import PolicyDraftCard from '../PolicyDraftCard'
import DeleteDraftPopup from '../DraftDeletePopup'
import DeleteDraftPopupOne from '../DeleteDraftPopupOne'
import useDeleteDraft from './useDeleteDraft'
import { PopupContainer } from './index.style'

const PopupDraftList = ({ show, onClose }) => {
  useEffect(() => {
    if (show) {
      document.body.style.overflowY = 'hidden'
    }
    return () => {
      document.body.style.overflowY = 'auto'
    }
  }, [show])

  const [{ getPolicyDraftListData, getPolicyDraftListMetaData }, _getPolicyDraftListRequest] =
    useGetPolicyDraftList()
  const getPolicyDraftListRequest = useCallback(
    (params) => {
      const query = {
        page: 1,
        page_size: 10,
        ...params,
      }
      _getPolicyDraftListRequest({ query })
    },
    [_getPolicyDraftListRequest]
  )

  const [{ GET_POLICY_DRAFT_LIST_LOADER }] = useLoaderContextValue()
  const [{ getPolicyDraftListStatus, GET_POLICY_DRAFT_LIST_ERROR }] = useErrorContextValue()
  const setPolicyState = useSetPolicyState()

  useEffect(() => {
    if (!show || getPolicyDraftListData?.length > 0) return
    if (GET_POLICY_DRAFT_LIST_ERROR) {
      ShowSnackbar.error({ text: getPolicyDraftListStatus })
      return
    }
    getPolicyDraftListRequest()
  }, [
    show,
    getPolicyDraftListRequest,
    getPolicyDraftListData,
    getPolicyDraftListStatus,
    GET_POLICY_DRAFT_LIST_ERROR,
    setPolicyState,
  ])

  const {
    isShowPopupSingle,
    isShowPopupMultiple,
    closePopup,
    isCheckAll,
    checkedDraftIds,
    handleCheckSingle,
    handleCheckAll,
    handleShowPopupDeleteSingle,
    handleConfirmDeleteSingle,
    handleShowPopupDeleteMultiple,
    handleConfirmDeleteMultiple,
  } = useDeleteDraft({ show, getPolicyDraftListData, getPolicyDraftListRequest })

  return createPortal(
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title="Selesaikan Pengajuan"
      showHeader
      backGroundColor={AgentColorPallette.primary}
      titleStyle={{
        color: AgentColorPallette.darkCharcoal,
        size: '12px',
        weight: '800',
      }}
      zIndex={3}
    >
      <PopupContainer>
        <CircularLoader isLoading={GET_POLICY_DRAFT_LIST_LOADER && !getPolicyDraftListData}>
          {getPolicyDraftListData && (
            <>
              <div className="multicheck-container">
                <div className="multicheck" onClick={handleCheckAll}>
                  <CustomCheckbox
                    isChecked={isCheckAll}
                    onChange={handleCheckAll}
                    color={AgentColorPallette.white}
                    bgColor={AgentColorPallette.darkCharcoal}
                  />
                  <div>Semua Polis</div>
                </div>
                <button
                  type="button"
                  className="btn-multidelete"
                  onClick={(e) => {
                    e.stopPropagation()
                    handleShowPopupDeleteMultiple()
                  }}
                >
                  Hapus
                </button>
              </div>
              <div className="list-container">
                {getPolicyDraftListData.map((draft, i) => (
                  <div className="card-wrapper" key={i}>
                    <CustomCheckbox
                      isChecked={checkedDraftIds.includes(draft?.id)}
                      onChange={() => handleCheckSingle(draft?.id)}
                      color={AgentColorPallette.white}
                      bgColor={AgentColorPallette.darkCharcoal}
                    />
                    <PolicyDraftCard
                      draftData={draft}
                      showActions
                      onClickDelete={() => handleShowPopupDeleteSingle(draft?.id)}
                    />
                  </div>
                ))}
                <LazyLoader
                  pageSize={10}
                  responseData={{ data: getPolicyDraftListData }}
                  metaData={getPolicyDraftListMetaData}
                  request={getPolicyDraftListRequest}
                />
              </div>
            </>
          )}
        </CircularLoader>
      </PopupContainer>

      <DeleteDraftPopupOne
        show={isShowPopupSingle}
        onClose={closePopup}
        onDeleteDraft={handleConfirmDeleteSingle}
      />
      <DeleteDraftPopup
        show={isShowPopupMultiple}
        onClose={closePopup}
        onDeleteDraftAll={handleConfirmDeleteMultiple}
        policyNumber={checkedDraftIds.length}
      />
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default PopupDraftList
