import { updateLoader, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useState } from 'react'
import { Carousel } from 'react-responsive-carousel'
import { useHistory } from 'react-router'
import { CustomText } from '../../../../../components'
import { getOfflineQuotePathOnStatus } from '../../../../../helpers/data'
import { WHITE_DOC_ICON } from '../../../../../images/imageUrl'
import { LANG_STRINGS } from '../../../../../lang'
import { useGetOfflineAlerts, useUpdateOfflineAlert } from '../../state/hooks/useDashboard'
import { AlertsCarouselStyle, OfflineAlertsStyle } from './index.style'
import 'react-responsive-carousel/lib/styles/carousel.min.css'

function OfflineAlerts() {
  const [{ getOfflineAlertsData = [] }, offlineAlertsRequest] = useGetOfflineAlerts()
  const [{ GET_OFFLINE_ALERTS_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [, updateOfflineAlertReq] = useUpdateOfflineAlert()
  const history = useHistory()
  const [showAlert, setShowAlert] = useState(true)

  useEffect(() => {
    if (GET_OFFLINE_ALERTS_LOADER === undefined) {
      offlineAlertsRequest()
    }
  }, [GET_OFFLINE_ALERTS_LOADER, offlineAlertsRequest])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_OFFLINE_ALERTS_LOADER: undefined,
          UPDATE_OFFLINE_ALERT: undefined,
        })
      )
    }
  }, [dispatchLoader])

  const onClose = useCallback(
    (id) => {
      // handle to remove the error from the dashboard container
      setShowAlert(false)
      updateOfflineAlertReq({
        id,
      })
    },
    [updateOfflineAlertReq]
  )

  const handleViewOffer = useCallback(
    (status, id, alertId, redirectUrl) => {
      if (redirectUrl) {
        window.location.href = redirectUrl
      } else {
        history.push({
          pathname: getOfflineQuotePathOnStatus(status, id),
        })
      }

      onClose(alertId)
    },
    [history, onClose]
  )

  return (
    showAlert &&
    !!getOfflineAlertsData.length && (
      <AlertsCarouselStyle>
        <Carousel showThumbs={false} showStatus={false} showArrows showIndicators={false}>
          {getOfflineAlertsData.map((alert) => (
            <OfflineAlertsStyle align="center" key={alert.id}>
              <div>
                <img src={WHITE_DOC_ICON} alt="" />
              </div>
              <CustomText weight={600} padRight="10px" padLeft="10px" className="warning-flex">
                {alert.description}
                <span
                  className="view-offline-details"
                  onClick={() =>
                    handleViewOffer(
                      alert.title,
                      alert.reference_model_id,
                      alert.id,
                      alert.redirect_url
                    )
                  }
                >
                  {LANG_STRINGS.viewOffer}
                </span>
              </CustomText>
              <div className="warning-close" onClick={() => onClose(alert.id)}>
                <i className="fas fa-times" />
              </div>
            </OfflineAlertsStyle>
          ))}
        </Carousel>
      </AlertsCarouselStyle>
    )
  )
}

export default OfflineAlerts
