import { useMemo } from 'react'
import { DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import Heading from '../../../../../components/Heading'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { useUpdateGlobal } from '../../../../../state/globalState/hooks/useGlobalContext'
import { checkIsLvAdmin, checkIsLvAgent } from '../../../../../helpers/checkAgentTags'
import useEventTracker from '../../../../../hooks/trackers'
import { POLICY_ACTION_ITEM } from '../../constants'
import { PolicyActionCardStyle, PolicyHeadingStyle } from './index.style'

function PolicyActionCard({ history }) {
  const [{ agentDetails = {} }] = useUpdateGlobal()
  const { trackUserEvent } = useEventTracker()

  const showDownlineBtn = useMemo(() => checkIsLvAgent(agentDetails) && !checkIsLvAdmin(agentDetails), [agentDetails])
  const hideRenewalBtn = useMemo(() => !checkIsLvAgent(agentDetails), [agentDetails])

  return (
    <PolicyHeadingStyle>
      <Heading title="Layanan Lainnya" />
      <PolicyActionCardStyle>
        {POLICY_ACTION_ITEM({ history, trackUserEvent })
          .filter((item) => {
            if (!showDownlineBtn && item.id === 'downline_button_home') return false
            if (hideRenewalBtn && item.id === 'renewal_policy_button_home') return false
            return true
          })
          .map((item) => (
            <DisplayFlexCCC
              id={item.id}
              key={item.id}
              className="policy-action-item"
              data-gtm-element-id={item.id}
              onClick={item.onClick}
            >
              <img src={item.icon} alt="" data-gtm-element-id={item.id} width={24} />
              <CustomText
                color={AgentColorPallette.darkCharcoal}
                size="0.75em"
                textAlign="center"
                top="6px"
                data-gtm-element-id={item.id}
              >
                {item.title}
              </CustomText>
            </DisplayFlexCCC>
          ))}
      </PolicyActionCardStyle>
    </PolicyHeadingStyle>
  )
}

export default PolicyActionCard
