import { ConfigUrl } from '../../../../configs/url'

export const DASHBOARD_ACTIONS = {
  GET_OFFLINE_ALERTS_REQUEST: 'GET_OFFLINE_ALERTS_REQUEST',
  GET_OFFLINE_ALERTS: 'GET_OFFLINE_ALERTS',

  UPDATE_OFFLINE_ALERT_REQUEST: 'UPDATE_OFFLINE_ALERT_REQUEST',
  UPDATE_OFFLINE_ALERT: 'UPDATE_OFFLINE_ALERT',

  OFFLINE_QUOTE_LIST_REQUEST: 'OFFLINE_QUOTE_LIST_REQUEST',
  OFFLINE_QUOTE_LIST: 'OFFLINE_QUOTE_LIST',

  NOTIFICATION_DETAILS_REQUEST: 'NOTIFICATION_DETAILS_REQUEST',
  NOTIFICATION_DETAILS: 'NOTIFICATION_DETAILS',
}

export const getOfflineAlerts = () => ({
  type: DASHBOARD_ACTIONS.GET_OFFLINE_ALERTS_REQUEST,
  payload: {
    url: ConfigUrl.agentAlertsForOfflineInfoApi,
    method: 'GET',
  },
})

export const updateOfflineAlert = (payload) => ({
  type: DASHBOARD_ACTIONS.UPDATE_OFFLINE_ALERT_REQUEST,
  payload: {
    url: ConfigUrl.offlineAlertUpdateApi(payload.id),
    method: 'POST',
  },
})

export const getOfflineQuotesList = (payload = {}) => ({
  type: DASHBOARD_ACTIONS.OFFLINE_QUOTE_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.offlineQuoteListApi,
  },
})

export const getNotificationDetails = (payload = {}) => ({
  type: DASHBOARD_ACTIONS.NOTIFICATION_DETAILS_REQUEST,
  payload: {
    query: payload,
    method: 'GET',
    url: ConfigUrl.getNotificationDetailsApi,
  },
})
