import { useCallback, useMemo, useState } from 'react'
import { useHistory } from 'react-router'
import Cookies from 'universal-cookie'
import { checkIsCorporateAgent } from '../../constants/appConstants'
import { EMAIL_KTP_WARNING_COOKIE } from '../../constants/cookies'
import { LANG_STRINGS } from '../../lang'
import { WarningNotificationStyle } from './index.style'

const cookies = new Cookies()

function WarningNotification({ isStaffAgent, getAgentDetailData }) {
  const history = useHistory()

  const isCorporateAgent = checkIsCorporateAgent(getAgentDetailData?.agent_type)

  const isDocVerified = useMemo(() => {
    if (isCorporateAgent)
      return getAgentDetailData?.is_nib_verified !== false
    else
      return getAgentDetailData?.is_ktp_verified !== false
  }, [isCorporateAgent, getAgentDetailData])

  const [isShowWarning, setIsShowWarning] = useState(
    cookies.get(EMAIL_KTP_WARNING_COOKIE) !== 'false'
  )

  const handleClose = useCallback((e) => {
    e.stopPropagation()
    e.preventDefault()
    setIsShowWarning(false)

    cookies.set(EMAIL_KTP_WARNING_COOKIE, 'false', {
      path: '/',
      maxAge: 60 * 60 * 24, // store for 1 month
    })
  }, [])

  if (!isStaffAgent && !isDocVerified && isShowWarning) {
    return (
      <WarningNotificationStyle>
        <div className='warning-text' onClick={() => history.push('/my-profile')}>
          {isCorporateAgent
            ? LANG_STRINGS.corporateNibVerificationWarning
            : LANG_STRINGS.ktpVerificationWarning
          }
        </div>
        <div className='warning-close' onClick={handleClose}>
          <i className='fas fa-times' />
        </div>
      </WarningNotificationStyle>
    )
  }
  return null
}

export default WarningNotification
