import { useCallback, useEffect } from 'react'
import { useHistory } from 'react-router'
import { useErrorContextValue } from '@pasarpolis/common-react-hooks'
import Heading from '../../../../../components/Heading'
import ShowSnackbar from '../../../../../components/ShowNotification'
import PolicyApplicationCard from '../../../Policy/pages/TransactionList/container/components/PolicyApplicationCard'
import { useGetPolicyList } from '../../../Policy/state/hooks/usePolicyState'
import { TransactionsStyle } from './index.style'

function LatestTransactions() {
  const history = useHistory()

  const [{ getPolicyListData, getPolicyListMetaData }, _getPolicyListRequest] = useGetPolicyList()
  const getPolicyListRequest = useCallback(
    (params = {}) => {
      const query = {
        page: 1,
        page_size: 5,
        ...params,
      }
      _getPolicyListRequest({ query })
    },
    [_getPolicyListRequest]
  )

  const [{ getPolicyListStatus, GET_POLICY_LIST_ERROR }] = useErrorContextValue()

  useEffect(() => {
    if (getPolicyListData?.length > 0) return
    if (GET_POLICY_LIST_ERROR) {
      ShowSnackbar.error({ text: getPolicyListStatus })
      return
    }
    getPolicyListRequest()
  }, [getPolicyListRequest, getPolicyListData, getPolicyListStatus, GET_POLICY_LIST_ERROR])

  return (
    <TransactionsStyle>
      <div className="heading-container">
        <Heading title="Transaksi Terakhir" />
        <div
          role="button"
          tabIndex={0}
          className="link-show-more"
          onClick={() => history.push('/transactions')}
        >
          Lihat Semua
        </div>
      </div>
      {getPolicyListData && getPolicyListMetaData?.total_records > 0 ? (
        <div className="policy-list-container">
          {getPolicyListData?.map((policyData, i) => (
            <PolicyApplicationCard
              key={i}
              policyData={policyData}
              onClickCard={() => history.push(`/transactions/${policyData.reference_id}/details`)}
            />
          ))}
        </div>
      ) : (
        <div className="no-content-text">
          <div>Saat ini Anda belum memiliki transaksi apapun</div>
        </div>
      )}
    </TransactionsStyle>
  )
}

export default LatestTransactions
