import { LANG_STRINGS } from '../../../../../lang'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CustomText } from '../../../../../components'
import { StyledModal, StyledRow } from './index.style'

function InsuranceTypeModal (props) {
  const { showOptionModal, insuranceType, onClose, onSubmit } = props

  return (
    <StyledModal
      heading={LANG_STRINGS.policyType}
      isOpen={showOptionModal}
      onClose={onClose}
    >
      {
        insuranceType.map((item, index) => (
          <StyledRow
            key={item.type}
            border={(index + 1) !== insuranceType.length}
            onClick={() => onSubmit(item.type)}
            id={`mobil-${item.type}`}
            data-gtm-element-id={`mobil-${item.type}`}
          >
            {item.imgUrl && <img className='row-icon' src={item.imgUrl} alt={item.title} />}
            <div className='row-title' data-gtm-element-id={`mobil-${item.type}`}>
              <CustomText
                color={AgentColorPallette.darkCharcoal}
                size='14px'
                weight={600}
                data-gtm-element-id={`mobil-${item.type}`}
              >
                {item.title}
              </CustomText>
              {item.subTitle && (
                <CustomText
                  color={AgentColorPallette.fontDarkerGrey}
                  size='10px'
                  data-gtm-element-id={`mobil-${item.type}`}
                >
                  {item.subTitle}
                </CustomText>
              )}
            </div>
            <i className='fas fa-angle-right arrow-gray' data-gtm-element-id={`mobil-${item.type}`} />
          </StyledRow>
        ))
      }
    </StyledModal>
  )
}
export default InsuranceTypeModal
