import {
  useLoaderContextValue,
  updateLoader,
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { lazy, Suspense, useState, useCallback, useEffect, useRef } from 'react'
import LazyLoad from 'react-lazyload'
import Cookies from 'universal-cookie'
import Products from '../components/Products'

import { Container, Loader } from '../../../../components'
import { useGlobalContextValue } from '../../../../contextProvider/GlobalContext'
import { DashboardWrapper } from './index.style'
import ShowSnackbar from '../../../../components/ShowNotification'
import { clearLocalStorage, getFromLocalStorageData } from '../../../../helpers/localstorage'
import {
  DASHBOARD_INFO,
  LOGIN_INFO_MODAL,
  SHOW_QUESTIONNAIRE_SUBMIT_MSG,
} from '../../../../constants/cookies'
import { LANG_STRINGS } from '../../../../lang'
import DownTimeNotification from '../components/DownTimeNotification'
import { ANDROID_BRIDGE } from '../../../../bridges/android'
import { useGetAgentDetails } from '../../../../state/globalState/hooks/useGlobalContext'
import WarningNotification from '../../../../components/WarningNotification'
import { MITRA_INTRO_CONFIG } from '../../../../configs/mitraIntro.config'
import introJs from 'intro.js'
import 'intro.js/introjs.css'
import '../../../../commonStyle/mitraIntroJs.css'
import { useGetTransactionsSummary } from '../../Policy/state/hooks/usePolicyState'
import { useGetNotificationDetail } from '../state/hooks/useDashboard'
import { DASHBOARD_INTRO } from '../constants'
import PolicyActionCard from '../components/PolicyActionCard'
import PromoBannerDetailModal from '../components/PromoBannerDetailModal'
import OfflineAlerts from '../components/OfflineAlerts'
import OfflineQuotesAlert from '../components/OfflineQuotesAlert'
import { getQueryParams, isIos } from '../../../../helpers/utility'
import DashboardTopSection from '../components/DashboardTopSection'
import NotificationBanner from '../components/NotificationBanner'
import MajorUpdateModal from '../components/MajorUpdateModal'
import LatestTransactions from '../components/LatestTransactions'
import { getLatestAppVersion } from '../../../../bridges/iOS'
import { checkIsLvAdmin } from '../../../../helpers/checkAgentTags'
import useEventTracker from '../../../../hooks/trackers'

const WelcomeLayer = lazy(() => import('../../../../components/WelcomeLayer'))
const KTPNPWPVerification = lazy(() => import('../../Wallet/components/KTPNPWPVerification'))
const LoginInformationModal = lazy(() => import('../../../../components/LoginInformationModal'))
const PromoCarousel = lazy(() => import('../components/PromoCarousel'))
const GojekCarousel = lazy(() => import('../components/GojekCarousel'))

const cookies = new Cookies()

function DashboardContainer({ history, ...props }) {
  const [headerPosition, setHeaderPosition] = useState('fixed')
  const [isMajorUpdateAvailable, setMajorUpdateStatus] = useState(false)
  const [notificationBanner, setNotificationBannerStatus] = useState(false)
  const questionsSubmit = useRef(
    typeof getFromLocalStorageData(SHOW_QUESTIONNAIRE_SUBMIT_MSG) !== 'object'
  )

  const { trackUserEvent } = useEventTracker()
  const hasTrackedDashboardView = useRef(false)

  const [modal, setModal] = useState({
    showModal: false,
    title: '',
    showBtn: '',
    imgUrl: '',
  })
  const [verificationDocModal, setVerificationDocModal] = useState(false)
  const [
    {
      isGojekDriver,
      isStaffAgent,
      isGuardianAgentLogin,
      isHideAgentBadges,
      getAgentDetailData = {},
    },
  ] = useGlobalContextValue()
  const that = useRef({
    introJs: {},
    isAgentDetailsCall: false,
  })
  const [{ GET_PRODUCT_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [showLayer, setShowLayer] = useState(cookies.get('isRegistrationSuccess') === 'true')
  const [showLoginInfoModal, setShowLoginInfoModal] = useState(
    isGuardianAgentLogin && cookies.get(LOGIN_INFO_MODAL) !== 'true'
  )
  const [, getAgentDetailsRequest] = useGetAgentDetails()
  const [{ getTransactionSummaryData = {} }, getTransactionSummaryReq] = useGetTransactionsSummary()
  const [{ notificationDetailsData }, getNotificationDetailsRequest] = useGetNotificationDetail()
  const [{ notificationDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  const startIntroJs = useCallback(() => {
    setHeaderPosition('absolute')
    setTimeout(() => {
      that.current.introJs.setOptions({
        steps: DASHBOARD_INTRO,
        tooltipClass: 'mitra-intro-tooltip',
        ...MITRA_INTRO_CONFIG,
      })
      document.body.style['max-width'] = 'inherit'
      that.current.introJs.start()
    }, 1000)

    // function called when exist from the intro js
    that.current.introJs.onexit(() => {
      cookies.set(DASHBOARD_INFO, 'false', {
        path: '/',
        maxAge: 60 * 60 * 24 * 365, // store for year
      })
      document.body.style['max-width'] = ''
      setHeaderPosition('fixed')
    })
  }, [])

  const convertVersionString = (str = '') => {
    return str.split('.').join('')
  }

  const checkVersionNumber = useCallback(() => {
    if (isIos()) {
      let latestIOSVersion = ''
      const blockerIOSVersion = process.env.REACT_APP_BLOCKER_IOS_VERSION
      getLatestAppVersion().then((res) => {
        latestIOSVersion = res.toString() || ''
        console.log('is iOS version', res, blockerIOSVersion)
        let isBlockerVersion = false
        if (['staging', 'testing'].includes(process.env.REACT_APP_ENV)) {
          // format for version on standbox => 1.2.10-sandbox
          // latestIOSVersion = +(latestIOSVersion.split('-')[0].split('.')[2]) // on sandbox we have diffent version format (1.2.10 < 1.1.11)
          // blockerIOSVersion = +(blockerIOSVersion.split('.')[2])
          isBlockerVersion = latestIOSVersion < blockerIOSVersion
        } else {
          isBlockerVersion =
            convertVersionString(latestIOSVersion) < convertVersionString(blockerIOSVersion)
        }
        if (isBlockerVersion) {
          setMajorUpdateStatus(false)
        }
        return false
      })
    } else if (ANDROID_BRIDGE.getVersionCode) {
      let latestAndriodVersion = ''
      const blockerAndriodVersion = process.env.REACT_APP_BLOCKER_ANDRIOD_VERSION
      ANDROID_BRIDGE.getVersionCode((res) => {
        latestAndriodVersion = res || ''
      })
      if (['staging', 'testing'].includes(process.env.REACT_APP_ENV)) {
        // latestAndriodVersion = +(latestAndriodVersion.split('-')[0].split('.')[2])
        // blockerAndriodVersion = +(blockerAndriodVersion.split('.')[2])
        return latestAndriodVersion.toString() < blockerAndriodVersion
      }
      return (
        convertVersionString(latestAndriodVersion) < convertVersionString(blockerAndriodVersion)
      )
    }
  }, [])

  useEffect(() => {
    if (!hasTrackedDashboardView.current && getAgentDetailData?.agent_code !== undefined) {
      trackUserEvent('[Mitra] Enter Homepage')
      hasTrackedDashboardView.current = true
    }
  }, [trackUserEvent, getAgentDetailData?.agent_code])

  useEffect(() => {
    if (getQueryParams('notif_id')) {
      const notifId = getQueryParams('notif_id')
      getNotificationDetailsRequest({ notif_id: notifId })
    }
    getTransactionSummaryReq()
  }, [getTransactionSummaryReq, getNotificationDetailsRequest, checkVersionNumber])

  useEffect(() => {
    if (notificationDetailsStatus === 'success') {
      const { extra_data: extraData, description } = notificationDetailsData
      setNotificationBannerStatus(true)
      that.current.notificationBannerData = {
        description,
        image: extraData?.image,
      }
      resetError(['notificationDetailsStatus'])
    }
  }, [notificationDetailsStatus, notificationDetailsData, resetError])

  useEffect(() => {
    if (isGojekDriver && cookies.get(DASHBOARD_INFO) !== 'false') {
      that.current.introJs = introJs()
      setTimeout(() => {
        startIntroJs()
      }, 500)
    }
  }, [isGojekDriver, startIntroJs])

  useEffect(() => {
    if (!that.current.isAgentDetailsCall) {
      that.current.isAgentDetailsCall = true
      // getAgentDetailsRequest()
    }
  }, [getAgentDetailsRequest])

  useEffect(() => {
    if (false && getAgentDetailData.questions_enable && !questionsSubmit.current) {
      // if questions enable then redirect the agent to
      // questionnaire and then decide the steps
      dispatchLoader(
        updateLoader({
          GET_AGENT_DETAIL_LOADER: undefined,
        })
      )
      history.replace('/review/1/questions')
    }
  }, [history, getAgentDetailData.questions_enable, dispatchLoader])

  useEffect(() => {
    if (questionsSubmit.current) {
      // handle to show snack bar
      ShowSnackbar.success({
        visible: true,
        text: LANG_STRINGS.congratsSuccessfullyLoggedInAsPartner,
      })
      getAgentDetailsRequest()
      clearLocalStorage()
      questionsSubmit.current = false
    }
    if (ANDROID_BRIDGE.whiteListBridge) {
      ANDROID_BRIDGE.whiteListBridge([
        'pasarpolis-pwa-dev.prospark.co',
        'pasarpolis-pwa-stg.prospark.co',
      ])
    }
  }, [getAgentDetailsRequest])

  useEffect(() => {
    return () => {
      clearLocalStorage()
    }
  }, [])

  const handleLoginInfoModal = useCallback(() => {
    setShowLoginInfoModal((showLoginInfoModal) => !showLoginInfoModal)
    cookies.set(LOGIN_INFO_MODAL, 'true', {
      path: '/',
    })
  }, [])

  useEffect(() => {
    if (!showLoginInfoModal && isGuardianAgentLogin && cookies.get(LOGIN_INFO_MODAL) !== 'true') {
      handleLoginInfoModal()
    }
  }, [handleLoginInfoModal, isGuardianAgentLogin, showLoginInfoModal])

  const handleCloseModal = useCallback(() => {
    setVerificationDocModal(false)
  }, [])

  const handleToReferral = useCallback(() => {
    if (!isStaffAgent) {
      history.push('/refer-earn')
    }
  }, [history, isStaffAgent])

  const handleHideLayer = useCallback(() => {
    setShowLayer(false)
    cookies.set('isRegistrationSuccess', 'false', {
      path: '/',
      maxAge: 60 * 60 * 24 * 365, // store for 1 month
    })
  }, [])

  const handleShowPromoModal = useCallback((modalData) => {
    setModal({
      showModal: true,
      ...modalData,
    })
  }, [])

  const handleClosePromoModal = useCallback(() => {
    setModal({
      showModal: false,
    })
  }, [])

  return (
    <Container
      showFaq
      showNotificationIcon
      loader={GET_PRODUCT_LOADER}
      headerPosition={headerPosition}
      typeHeader="greeting"
      className="bg-white"
      showOJKText
    >
      <DashboardWrapper isGojek={isGojekDriver}>
        {isMajorUpdateAvailable && (
          <MajorUpdateModal
            title={LANG_STRINGS.updateYourApp}
            content={LANG_STRINGS.msgForAppUpdate}
            visible={isMajorUpdateAvailable}
            okBtnText={LANG_STRINGS.updateNow}
            onOK={() => window.open('https://mitra-app.pasarpolis.com/yoxH', '_self')}
          />
        )}
        {notificationBanner && (
          <NotificationBanner
            data={that.current.notificationBannerData}
            onClose={() => setNotificationBannerStatus(false)}
          />
        )}
        <OfflineAlerts />
        <WarningNotification
          isStaffAgent={isStaffAgent}
          getAgentDetailData={getAgentDetailData}
        />

        <DashboardTopSection
          isHideAgentBadges={isHideAgentBadges}
          getAgentDetailData={getAgentDetailData}
          getTransactionSummaryData={getTransactionSummaryData}
        />
        <Products agentData={getAgentDetailData} history={history} />
        <PolicyActionCard history={history} />
        {process.env.REACT_APP_SHOW_OFFLINE === 'true' && !checkIsLvAdmin(getAgentDetailData) && (
          <OfflineQuotesAlert />
        )}
        {!isGojekDriver &&
          getAgentDetailData.agent_code &&
          getAgentDetailData?.category !== undefined && (
            <LazyLoad height={168} once>
              <Suspense fallback={<Loader visible bgColor="transparent" />}>
                <PromoCarousel
                  agentCode={getAgentDetailData.agent_code}
                  isStaffAgent={isStaffAgent}
                  isGojekDriver={isGojekDriver}
                  onPromoModal={handleShowPromoModal}
                  onReferralClick={handleToReferral}
                  history={history}
                />
              </Suspense>
            </LazyLoad>
          )}
        {showLayer && <WelcomeLayer onCloseLayer={handleHideLayer} />}
        {getAgentDetailData.agent_code && !checkIsLvAdmin(getAgentDetailData) && (
          <LazyLoad height={168} once>
            <Suspense fallback={<Loader visible bgColor="transparent" />}>
              <LatestTransactions />
            </Suspense>
          </LazyLoad>
        )}
        {isGojekDriver && (
          <LazyLoad height={168} once>
            <Suspense fallback={<Loader visible bgColor="transparent" />}>
              <GojekCarousel onClickCard={handleToReferral} history={history} />
            </Suspense>
          </LazyLoad>
        )}
        {verificationDocModal && (
          <Suspense fallback={<Loader visible bgColor="transparent" />}>
            <KTPNPWPVerification
              showModal={verificationDocModal}
              onClose={handleCloseModal}
              history={history}
            />
          </Suspense>
        )}
        {showLoginInfoModal && (
          <LazyLoad height={168} once>
            <Suspense fallback={<Loader visible />}>
              <LoginInformationModal
                showModal={showLoginInfoModal}
                onClose={handleLoginInfoModal}
                agentName={getAgentDetailData.name}
              />
            </Suspense>
          </LazyLoad>
        )}
        {modal.showModal && (
          <PromoBannerDetailModal
            imgUrl={modal.imgUrl}
            showModal={modal.showModal}
            title={modal.title}
            showBtn={modal.showBtn}
            onReferralBtnClick={handleToReferral}
            onCloseModal={handleClosePromoModal}
          />
        )}
        <DownTimeNotification />
        <ShowSnackbar hideOkay />
      </DashboardWrapper>
    </Container>
  )
}

export default DashboardContainer
