import moment from 'moment'
import { useMemo } from 'react'
import { Row } from '../../commonStyle/index.style'
import { CustomText } from '..'
import { AgentColorPallette } from '../../configs/colorPallete'
import { getOfflineQuoteStatus } from '../../helpers/data'
import { LANG_STRINGS } from '../../lang'
import { PolicyCardStyle, PolicyStatusChip } from './index.style'
import { FLEET_POLICY } from '../../constants/pkgCode'
import { PRODUCT_LOGO } from '../../constants/productImgUrls'

function MVPolicyCard ({
  onClick, data = {}, className = '', hideBtmWarning,
  statusChipConfig = {}
}) {
  const offlineQuoteStatus = useMemo(() => getOfflineQuoteStatus(data.status), [data.status])
  const offlineVehicleInfo = useMemo(() => {
    if (data?.policy_details?.protection_case === FLEET_POLICY) {
      return LANG_STRINGS.fleet
    }
    if (data?.policy_details.region_code && data?.policy_details.region_code) {
      return `${data.policy_details.region_code} ${data.policy_details.vehicle_plate_no}`
    }
    return null
  }, [data])

  return (
    <PolicyCardStyle
      isWarning={data?.remarks && !hideBtmWarning}
      onClick={() => onClick(data)}
      className={className}
    >
      <div className='product-icon'>
        <img src={PRODUCT_LOGO[data.product_key]} alt='Product Icon' />
      </div>
      <div className='offline-card-right'>
        <div>
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size='11px'
            weight={800}
          >
            {data.request_no}
          </CustomText>
          <CustomText color={AgentColorPallette.black} size='1.1em' weight={800} bottom='0.8rem'>
            {data.customer_name} / {offlineVehicleInfo}
          </CustomText>
        </div>
        <div>
          <PolicyStatusChip bgColor={offlineQuoteStatus.color} config={statusChipConfig}>
            {offlineQuoteStatus.text}
          </PolicyStatusChip>
          <Row align='center' justify='space-between' className='card-order-date'>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              size='10px'
            >
              {LANG_STRINGS.ordersAreMade}
            </CustomText>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              size='10px'
            >
              {data.created_at ? moment(data.created_at).format('DD MMM YYYY') : ''}
            </CustomText>
          </Row>
        </div>
      </div>
      {
        data?.remarks && !hideBtmWarning && (
          <CustomText
            size='11px'
            weight={800}
            className='card-warning'
          >
            {data.remarks}
          </CustomText>
        )
      }
    </PolicyCardStyle>
  )
}

export default MVPolicyCard
