import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

export const DashboardContext = createContext()

export const DashboardContextProvider = ({ children, ...props }) => {
  return (
    <DashboardContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {children}
    </DashboardContext.Provider>
  )
}

export const useDashboardContextValue = () => useContext(DashboardContext)
