import {
  CAR_PROTECTION,
  EXTENDED_WARRANTY_PROTECTION,
  PROPERTY_PROTECTION,
} from '../../../../../../../../constants/pkgCode'
import {
  getDateDifference,
  getRemainingDatetime,
  isDateAfter,
  isDateBefore,
} from '../../../../../../../../helpers/formatDate'

export const getDisplayedCustomerName = (data) => {
  const _customerName = data?.customer_data?.name || data?.customer_detail?.name
  switch (data?.product_code) {
    case CAR_PROTECTION:
    case EXTENDED_WARRANTY_PROTECTION:
      const regionPlate = data.region_code
        ? data.region_code + ' ' + data.vehicle_plate_no
        : data.vehicle_plate_no
      return `${_customerName || '-'} / ${regionPlate || '-'}`
    case PROPERTY_PROTECTION:
      if (data?.customer_data?.type === 'corporate') {
        return data?.customer_data?.corporate_data?.name
      } else {
        return _customerName
      }
    default:
      return _customerName
  }
}

export const getPolicyStatusPill = (policyData) => {
  switch (policyData?.attributes?.policy_status) {
    case 'ACTIVE':
      if (isDateAfter(policyData?.coverage_end_date, new Date())) {
        return <div className="status-pill active">Polis Aktif</div>
      }
      return <div className="status-pill expired">Polis Berakhir</div>
    case 'PROVISIONAL_ISSUED':
      return <div className="status-pill provisional">Polis Terbit</div>
    case 'REJECTED':
      return <div className="status-pill rejected">Polis Ditolak</div>
    case 'CANCELLED':
      return <div className="status-pill cancelled">Polis Batal</div>
    case 'PENDING':
    case 'PENDING_DORMANT_COVERAGE':
    default:
      return <div className="status-pill in-progress">Polis Diproses</div>
  }
}

export const getPaymentStatusPill = (policyData) => {
  switch (policyData?.attributes?.payment_status) {
    case 'INSTALMENT_IN_PROGRESS':
    case 'MITRA_CONFIRMATION_PENDING':
    case 'NO_PAYMENT_MADE':
    case 'PROOF_APPROVED':
    case 'PROOF_SUBMITTED':
    case 'PROOF_UNDERPAYMENT':
    case 'PROOF_VERIFICATION_FAILED':
    case 'WAITING_FOR_PAYMENT':
    case 'ACTIVE':
      return <div className="status-pill payment-active">Menunggu Pembayaran</div>
    case 'COMPLETED':
      return <div className="status-pill payment-completed">Pembayaran Berhasil</div>
    case 'EXPIRED':
    case 'FAILED':
      return <div className="status-pill payment-failed">Pembayaran Gagal</div>
    default:
      return null
  }
}

export const getPaymentExpiryPill = (policyData) => {
  const expiryDate = policyData?.attributes?.payment_expiry_date
  if (!expiryDate) return null

  const acceptedUnits = ['D', 'h', 'm', 's']
  const diff = getDateDifference(expiryDate)
  const isMoreThan1Day = diff?.years > 0 || diff?.months > 0 || diff?.days > 0
  return (
    <div className={`status-pill ${isMoreThan1Day ? 'payment-warning' : 'payment-urgent'}`}>
      {getRemainingDatetime(expiryDate, new Date(), acceptedUnits)}
    </div>
  )
}

export const getRenewalExpiryPill = (policyData) => {
  const expiryDate = policyData?.coverage_end_date
  if (!expiryDate) return null

  const acceptedUnits = ['D', 'h', 'm', 's']
  const isExpired = isDateBefore(expiryDate, new Date(), true)
  if (isExpired) {
    return (
      <div className="status-pill renewal-expired">
        {getRemainingDatetime(expiryDate, new Date(), acceptedUnits)}
      </div>
    )
  }

  const diff = getDateDifference(expiryDate)
  const isAtLeast15Days = diff?.years > 0 || diff?.months > 0 || diff?.days >= 15
  if (isAtLeast15Days) {
    return (
      <div className="status-pill renewal-warning">
        {getRemainingDatetime(expiryDate, new Date(), acceptedUnits)}
      </div>
    )
  }
  return (
    <div className="status-pill renewal-urgent">
      {getRemainingDatetime(expiryDate, new Date(), acceptedUnits)}
    </div>
  )
}
