import { GuideBottomSheetStyle } from './index.style'
import BottomActionSheet from '../BottomActionSheet/index'
import { LANG_STRINGS } from '../../lang/index'
import { DisplayFlexRCC } from '../../commonStyle/index.style'
import Heading from '../Heading/index'
import ReactDOM from 'react-dom'

function GuideBottomSheet ({
  show, title = LANG_STRINGS.guide,
  guideData = {}, onClose = () => {}
}) {
  return ReactDOM.createPortal(
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title={title}
      zIndex={4}
      showHeader
    >
      <GuideBottomSheetStyle>
        {
          guideData.url && (
            <>
              <DisplayFlexRCC>
                <img src={guideData.url} alt='' height={220} />
              </DisplayFlexRCC>
              <Heading
                title={LANG_STRINGS.guide}
                size='0.8em'
              />
            </>
          )
        }
        <ul className='guide-terms'>
          {
            guideData?.terms?.map((term, index) => <li key={index}>{term}</li>)
          }
        </ul>
      </GuideBottomSheetStyle>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default GuideBottomSheet
