import { useCallback, useEffect, useState } from 'react'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../../../components/ShowNotification'
import { useSetPolicyState } from '../../../../../state/hooks/usePolicyState'
import { useDeleteDraft as useDeletePolicyDraft } from '../../../../../../../../state/globalState/hooks/useGlobalContext'

const POPUP = {
  DELETE_SINGLE: 'DELETE_SINGLE',
  DELETE_MULTIPLE: 'DELETE_MULTIPLE',
}

function useDeleteDraft({ show, getPolicyDraftListData, getPolicyDraftListRequest }) {
  const [, deleteDraftRequest] = useDeletePolicyDraft()

  const [{ deleteDraftStatus }] = useErrorContextValue()
  const setPolicyState = useSetPolicyState()
  const { resetError } = useResetError()

  const [showPopup, setShowPopup] = useState(null)
  const [isCheckAll, setIsCheckAll] = useState(false)
  const [checkedDraftIds, setCheckedDraftIds] = useState([])
  const [draftIdToDelete, setDraftIdToDelete] = useState(null)

  useEffect(() => {
    if (!show) {
      setShowPopup(false)
      setIsCheckAll(false)
      setCheckedDraftIds([])
      setDraftIdToDelete(null)
    }
  }, [show])

  const closePopup = useCallback(() => setShowPopup(null), [])

  const handleCheckAll = useCallback(() => {
    if (isCheckAll) {
      setIsCheckAll(false)
      setCheckedDraftIds([])
    } else {
      const all = getPolicyDraftListData.map((draft) => draft.id)
      setIsCheckAll(true)
      setCheckedDraftIds(all)
    }
  }, [isCheckAll, getPolicyDraftListData])

  const handleCheckSingle = useCallback((draftId) => {
    setCheckedDraftIds((prev) => {
      if (prev.includes(draftId)) {
        return prev.filter((id) => id !== draftId)
      }
      return [...prev, draftId]
    })
  }, [])

  const handleShowPopupDeleteSingle = useCallback((draftId) => {
    setDraftIdToDelete(draftId)
    setShowPopup(POPUP.DELETE_SINGLE)
  }, [])

  const handleConfirmDeleteSingle = useCallback(() => {
    if (!draftIdToDelete) return
    const payload = {
      body: { draft_ids: [draftIdToDelete] },
    }
    deleteDraftRequest(payload)
  }, [deleteDraftRequest, draftIdToDelete])

  const handleShowPopupDeleteMultiple = useCallback((draftId) => {
    setShowPopup(POPUP.DELETE_MULTIPLE)
  }, [])

  const handleConfirmDeleteMultiple = useCallback(() => {
    if (!checkedDraftIds.length) return
    const payload = {
      body: { draft_ids: checkedDraftIds },
    }
    deleteDraftRequest(payload)
  }, [deleteDraftRequest, checkedDraftIds])

  useEffect(() => {
    if (deleteDraftStatus === 'success') {
      ShowSnackbar.success({ text: 'Berhasil menghapus pengajuan' })
      resetError(['deleteDraftStatus'])
      setPolicyState({ getPolicyDraftListData: null })
      getPolicyDraftListRequest()
      setShowPopup(null)
      setIsCheckAll(false)
      setCheckedDraftIds([])
      setDraftIdToDelete(null)
    }
  }, [setPolicyState, resetError, deleteDraftStatus, getPolicyDraftListRequest])

  useEffect(() => {
    if (deleteDraftStatus && deleteDraftStatus !== 'success') {
      ShowSnackbar.error({ text: deleteDraftStatus })
    }
  }, [deleteDraftStatus])

  return {
    isShowPopupSingle: showPopup === POPUP.DELETE_SINGLE,
    isShowPopupMultiple: showPopup === POPUP.DELETE_MULTIPLE,
    closePopup,
    isCheckAll,
    checkedDraftIds,
    handleCheckAll,
    handleCheckSingle,
    handleShowPopupDeleteSingle,
    handleConfirmDeleteSingle,
    handleShowPopupDeleteMultiple,
    handleConfirmDeleteMultiple,
  }
}

export default useDeleteDraft
