import { useCallback } from 'react'
import {
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
  useServiceRequest,
} from '@pasarpolis/common-react-hooks'
import { useDynamicPurchaseFlowContext } from './context'
import {
  getPurchaseFlowConfigAction,
  setContextStateAction,
  resetContextStateAction,
  getPackageListAction,
  getPackageDetailAction,
  createPolicyDraftAction,
  updatePolicyDraftAction,
  getPolicyDraftAction,
  completePolicyDraftAction,
  getPolicyApplicationDetailAction,
  shareQuotationSlipAction,
  uploadBulkExcelAction,
  getPopupApiOptionsAction,
} from './state/actions'

export const useServiceCall = (actionsCall = () => {}) => {
  const [policyState, dispatch, setContextState, resetContextState] =
    useDynamicPurchaseFlowContext()
  const [dispatchCallApi] = useServiceRequest(dispatch)
  const [loaders, dispatchLoader] = useLoaderContextValue()
  const [errors, dispatchError] = useErrorContextValue()
  const { resetError } = useResetError()

  const request = useCallback(
    async (payload = {}) => {
      await dispatchCallApi(actionsCall({ ...payload }))
    },
    [dispatchCallApi, actionsCall]
  )

  return {
    state: policyState,
    request,
    loaders,
    dispatchLoader,
    errors,
    dispatchError,
    resetError,
    setContextState,
    resetContextState,
  }
}

export const useSetContextState = () => useServiceCall(setContextStateAction)
export const useResetContextState = () => useServiceCall(resetContextStateAction)

export const useGetPurchaseFlowConfig = () => useServiceCall(getPurchaseFlowConfigAction)

export const useGetPackageList = () => useServiceCall(getPackageListAction)
export const useGetPackageDetail = () => useServiceCall(getPackageDetailAction)

export const useCreatePolicyDraft = () => useServiceCall(createPolicyDraftAction)
export const useGetPolicyDraft = () => useServiceCall(getPolicyDraftAction)
export const useUpdatePolicyDraft = () => useServiceCall(updatePolicyDraftAction)
export const useCompletePolicyDraft = () => useServiceCall(completePolicyDraftAction)
export const useGetPolicyApplicationDetail = () => useServiceCall(getPolicyApplicationDetailAction)

export const useShareQuotationSlip = () => useServiceCall(shareQuotationSlipAction)
export const useUploadBulkExcel = () => useServiceCall(uploadBulkExcelAction)
export const useGetPopupApiOptions = () => useServiceCall(getPopupApiOptionsAction)
