import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useDashboardContextValue } from '../../context'
import {
  getOfflineAlerts,
  updateOfflineAlert,
  getOfflineQuotesList,
  getNotificationDetails,
} from '../actions'

export const useDashboardServiceCall = (actionsCall = () => {}) => {
  const [dashboardState, dispatch] = useDashboardContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(
    async (payload = {}) => {
      await callApi(
        actionsCall({
          ...payload,
        })
      )
    },
    [actionsCall, callApi]
  )

  return [dashboardState, request]
}

export const useGetOfflineAlerts = () => useDashboardServiceCall(getOfflineAlerts)

export const useUpdateOfflineAlert = () => useDashboardServiceCall(updateOfflineAlert)

// get notification detail
export const useGetNotificationDetail = () => useDashboardServiceCall(getNotificationDetails)

// use to get offline quote list api call
export const useGetOfflineQuoteList = () => useDashboardServiceCall(getOfflineQuotesList)
