import { updateLoader, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect } from 'react'
import { useHistory } from 'react-router-dom'
import { Row } from '../../../../../commonStyle/index.style'
import MVPolicyCard from '../../../../../components/MVPolicyCard'
import { LANG_STRINGS } from '../../../../../lang'
import { useGetOfflineQuoteList } from '../../state/hooks/useDashboard'
import { OfflineQuotesAlertStyle } from './index.style'
import { getOfflineQuotePathOnStatus } from '../../../../../helpers/data'
import Heading from '../../../../../components/Heading'

function OfflineQuotesAlert () {
  const [{ offlineQuoteListData = [] }, getOfflineQuoteListRequest] = useGetOfflineQuoteList()
  const [{ OFFLINE_QUOTE_LIST_LOADER }, dispatchLoader] = useLoaderContextValue()
  const history = useHistory()

  useEffect(() => {
    if (OFFLINE_QUOTE_LIST_LOADER === undefined) {
      getOfflineQuoteListRequest({
        query: {
          page_size: 5
        }
      })
    }
  }, [getOfflineQuoteListRequest, OFFLINE_QUOTE_LIST_LOADER])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        OFFLINE_QUOTE_LIST_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleTheCard = useCallback((data) => {
    history.push({
      pathname: getOfflineQuotePathOnStatus(data.status, (data.application_id || data.id), data.application_id)
    })
  }, [history])

  return !!offlineQuoteListData?.length && (
    <OfflineQuotesAlertStyle>
      <Heading className='offline-heading' title={LANG_STRINGS.fleetManualOrder} />
      <Row className='quotes-list-container' align='stretch'>
        {
          offlineQuoteListData.map((offlineQuote, index) => (
            <MVPolicyCard
              id={`offline_quote_list_${index}`}
              key={offlineQuote.id}
              onClick={() => handleTheCard(offlineQuote)}
              data={offlineQuote}
              hideBtmWarning
              className='quote-card-width'
              statusChipConfig={{
                size: '8px',
                padding: '5px 8px'
              }}
            />
          ))
        }
      </Row>
    </OfflineQuotesAlertStyle>
  )
}

export default OfflineQuotesAlert
