import { useState } from 'react'
import { generateYearArray, mapNumberToMonth } from '../../../helpers/utility'
import { BottomSheetSelectMonthContainerStyle } from './index.style'
import { LANG_STRINGS } from '../../../lang'
import { Button } from '../..'
import { Grid } from '../../../commonStyle/index.style'
import { monthOptions } from '../constant'
import AutoSearchBottomSheet from '../../DynamicForm/components/AutoSearchBottomSheet'
import moment from 'moment'

function BottomSheetSelectMonthContainer ({ month, year, setMonth, setYear, agentGwpRequest, onClose, agentCode }) {
  const [selectedMonth, setSelectedMonth] = useState(month)
  const [selectedYear, setSelectedYear] = useState(year)

  return (
    <BottomSheetSelectMonthContainerStyle>
      <Grid
        gridColumn='1fr 1fr'
        gridGap='1rem'
      >
        <AutoSearchBottomSheet
          title={LANG_STRINGS.year}
          data={generateYearArray(moment().year())}
          displayKey='year'
          dataKey='year'
          onChange={(e) => setSelectedYear(e.year)}
          defaultValue={{ year: selectedYear }}
        />
        <AutoSearchBottomSheet
          title={LANG_STRINGS.months}
          data={monthOptions()}
          displayKey='monthName'
          dataKey='value'
          onChange={(e) => setSelectedMonth(e.value)}
          defaultValue={{ monthName: mapNumberToMonth(month), value: selectedMonth }}
        />
      </Grid>
      <Button
        onClick={() => {
          agentGwpRequest({ month: selectedMonth + 1, year: selectedYear, agent_code: agentCode })
          setMonth(selectedMonth)
          setYear(selectedYear)
          onClose()
        }}
      >
        {LANG_STRINGS.show}
      </Button>
    </BottomSheetSelectMonthContainerStyle>
  )
}

export default BottomSheetSelectMonthContainer
