import { MultipleImgContainer, UploadFileStyle } from './index.style'
import FormItemLabel from '../../FormItemLabel/index'
import {
  DisplayCircleIcon,
  DisplayFlexCCC,
  Error,
  Row,
} from '../../../../../commonStyle/index.style'
import ShowSnackbar from '../../../../ShowNotification'
import {
  useUploadFile,
  useUploadKTPNPWPDoc,
} from '../../../../Upload/state/hooks/useUploadFileState'
import { useCallback, useRef, useEffect, useState } from 'react'
import { getFileExtension, getFileNameFromUrl } from '../../../../../helpers/utility'
import {
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { useUploadFileContextValue } from '../../../../Upload/context'
import { resetUploadFileState } from '../../../../Upload/state/actions'
import { UPLOAD_ICON } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang/index'
import PdfContainer from '../../../../PdfContainer'
import { MINI_HELP_ICON, GOLD_UPLOAD_ICON, TRASH_ICON } from '../../../../../images/imageUrl'
import { CustomText } from '../../../..'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import GuideBottomSheet from '../../../../GuideBottomSheet'
import LoaderSvg from '../../../../CircularLoader/LoaderSvg'
import ImageViewer from '../../../../ImageViewer/index'
import { INPUT_FILE_TYPE } from '../../../../../constants/file'

function UploadFileContainer({
  title,
  required,
  name,
  isMultiple,
  fileType,
  defaultValue,
  onChange,
  height,
  width,
  hideUpload,
  className,
  showGuideBtn,
  guideData = {},
  maxUpload,
  error,
  uploadKTPNPWP,
  docType,
  disabled,
}) {
  const [uploadLink, setUploadLink] = useState(defaultValue || '')
  const [showGuide, setShowGuide] = useState(false)
  const [showViewer, setShowViewer] = useState({
    show: false,
    activeIndex: 0,
  })
  const [{ getUploadLinkData }, uploadFileRequest] = useUploadFile()
  const [{ uploadDocData: uploadKTPNPWPDocData }, uploadKTPNPWPDocRequest] = useUploadKTPNPWPDoc()
  const [{ GET_UPLOAD_LINK_LOADER, UPLOAD_DOC_LOADER }] = useLoaderContextValue()
  const [{ getUploadLinkStatus, uploadKTPNPWPDocStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [, dispatchUploadFile] = useUploadFileContextValue()
  const [isImgUploading, setIsImgUploading] = useState(false)
  const [uploadedImgs, setUploadedImgs] = useState((isMultiple && defaultValue) || [])
  const that = useRef({
    uploadCount: 0,
    totalFiles: uploadedImgs.length || 0,
    currentFileUploadName: '',
    uploadedImgs: uploadedImgs || [],
    fileUploadedName: !isMultiple && defaultValue && getFileNameFromUrl(defaultValue),
  })

  const uploadFiles = useCallback(() => {
    const file = that.current.files[that.current.uploadCount]
    if (file.size > 11000000) {
      ShowSnackbar.error({
        visible: true,
        text: LANG_STRINGS.fileSizeLarge,
      })
      return
    }
    ++that.current.uploadCount
    const formData = new FormData()
    formData.append('file', file)
    if (uploadKTPNPWP) {
      uploadKTPNPWPDocRequest({
        body: formData,
        name: docType,
      })
    } else {
      uploadFileRequest({
        body: formData,
      })
    }
  }, [uploadFileRequest, uploadKTPNPWPDocRequest, uploadKTPNPWP, docType])

  useEffect(() => {
    if (uploadKTPNPWPDocData?.url && that.current.currentFileUploadName === name) {
      dispatchUploadFile(
        resetUploadFileState({
          uploadKTPNPWPDocData: undefined,
        })
      )
      that.current.currentFileUploadName = ''
      onChange(
        [
          {
            document_type: uploadKTPNPWPDocData.document_type,
            url: uploadKTPNPWPDocData.url,
            document_uuid: uploadKTPNPWPDocData.id,
          },
        ],
        name
      )
      setUploadLink(uploadKTPNPWPDocData?.url)
    } else if (uploadKTPNPWPDocStatus && uploadKTPNPWPDocStatus !== 'success') {
      setIsImgUploading(false)
      resetError(['uploadKTPNPWPDocStatus'])
    }
  }, [
    uploadKTPNPWPDocData,
    uploadKTPNPWPDocStatus,
    resetError,
    dispatchUploadFile,
    onChange,
    name,
    getUploadLinkData,
  ])

  useEffect(() => {
    if (getUploadLinkData?.url && that.current.currentFileUploadName === name) {
      dispatchUploadFile(
        resetUploadFileState({
          getUploadLinkData: undefined,
        })
      )
      if (isMultiple) {
        setUploadedImgs((uploadedImgs) => {
          if (that.current.viewIndexChange) {
            uploadedImgs[that.current.viewIndexChange] = { ...getUploadLinkData }
            that.current.uploadedImgs = [...uploadedImgs]
            onChange(that.current.uploadedImgs)
            return [...uploadedImgs]
          } else {
            return [...uploadedImgs, getUploadLinkData]
          }
        })
        that.current.uploadedImgs = [...that.current.uploadedImgs, getUploadLinkData]
        if (that.current.uploadCount + 1 <= that.current.totalFiles) {
          uploadFiles()
        } else {
          that.current.currentFileUploadName = ''
          setIsImgUploading(false)
          onChange(that.current.uploadedImgs)
        }
      } else {
        that.current.currentFileUploadName = ''
        onChange(getUploadLinkData?.url, name)
        setUploadLink(getUploadLinkData?.url)
      }
    } else if (getUploadLinkStatus && getUploadLinkStatus !== 'success') {
      setIsImgUploading(false)
      resetError(['getUploadLinkStatus'])
    }
  }, [
    dispatchUploadFile,
    name,
    getUploadLinkData,
    getUploadLinkStatus,
    onChange,
    isMultiple,
    uploadFiles,
    uploadedImgs,
    resetError,
  ])

  const handleShowHelp = useCallback(() => {
    setShowGuide(true)
  }, [])

  const handleMultipleUpload = useCallback(
    (file) => {
      if (file.files.length > maxUpload || uploadedImgs?.length > maxUpload) {
        ShowSnackbar.error({
          visible: true,
          text: `Maksimal ${maxUpload} file diperbolehkan`,
        })
        return
      }
      that.current.totalFiles = file.files.length
      that.current.files = file.files
      that.current.uploadCount = 0
      setIsImgUploading(true)
      uploadFiles()
      ShowSnackbar.success({
        visible: true,
        text: LANG_STRINGS.uploadStart,
      })
    },
    [uploadFiles, maxUpload, uploadedImgs]
  )

  const handleUpload = useCallback(
    (e, inputName) => {
      const file = document.getElementById(inputName || name)
      if ('files' in file && file.files.length) {
        if (isMultiple) {
          that.current.currentFileUploadName = name
          handleMultipleUpload(file)
          return
        }
        if (file.files[0]) {
          that.current.currentFileUploadName = name
          if (file.files[0].size > 11000000) {
            ShowSnackbar.error({
              visible: true,
              text: 'Ukuran file terlalu besar',
            })
          } else {
            ShowSnackbar.success({
              visible: true,
              text: 'Pengunggahan dimulai',
            })
            const formData = new FormData()
            formData.append('file', file.files[0])
            that.current.fileUploadedName = file.files[0].name
            if (uploadKTPNPWP) {
              uploadKTPNPWPDocRequest({
                body: formData,
                name: docType,
              })
            } else {
              uploadFileRequest({
                body: formData,
              })
            }
          }
        }
      }
    },
    [
      name,
      handleMultipleUpload,
      isMultiple,
      uploadFileRequest,
      docType,
      uploadKTPNPWPDocRequest,
      uploadKTPNPWP,
    ]
  )

  const handleRemovePhoto = useCallback(
    (e) => {
      e.stopPropagation()
      setUploadLink('')
      onChange && onChange('', name)
    },
    [name, onChange]
  )

  const handleDelete = useCallback(
    (index, name) => {
      if (isMultiple) {
        setUploadedImgs((oldImgs) => {
          oldImgs.splice(index, 1)
          that.current.uploadedImgs.splice(index, 1)
          onChange(oldImgs, name)
          return [...oldImgs]
        }, [])
      } else if (name) {
        setUploadLink('')
        setShowViewer({ show: false })
        onChange('', name)
      }
    },
    [isMultiple, onChange]
  )

  const handleShowViewer = useCallback((index, url) => {
    setShowViewer({
      show: true,
      activeIndex: url ? 0 : index,
    })
  }, [])

  const handleChangeViewer = useCallback(
    (e, inputName, index) => {
      that.current.viewIndexChange = index
      handleUpload(e, inputName)
    },
    [handleUpload]
  )

  const getImageContainer = useCallback(
    (imgUrl) => {
      const ext = getFileExtension(imgUrl)
      if (ext === 'pdf') {
        return (
          <PdfContainer url={imgUrl} fileName={that.current.fileUploadedName}>
            {!hideUpload && (
              <Row align="center" justify="center" className="upload-change-btn">
                <span>{LANG_STRINGS.change}</span>&nbsp;&nbsp;
                <input
                  type="file"
                  className="upload-file-input"
                  id={name}
                  name={name}
                  onChange={handleUpload}
                  accept={
                    window.PPBridge ? INPUT_FILE_TYPE.IMAGE : fileType || INPUT_FILE_TYPE.IMAGE
                  }
                />
                <i className="fas fa-pen" />
              </Row>
            )}
          </PdfContainer>
        )
      }
      return (
        <div
          className={`image-display ${width && 'small-img-container'}`}
          style={{
            backgroundImage: `url(${imgUrl})`,
            height: height || '100px',
            marginBottom: '0.2rem',
            width: width || '100%',
          }}
          onClick={() => handleShowViewer(0, imgUrl)}
        >
          {!disabled && (
            <DisplayCircleIcon
              className="img-delete-icon"
              bgColor={AgentColorPallette.white}
              onClick={handleRemovePhoto}
            >
              <img src={TRASH_ICON} width={12} height="auto" alt="" />
            </DisplayCircleIcon>
          )}
        </div>
      )
    },
    [
      handleUpload,
      width,
      fileType,
      handleShowViewer,
      name,
      height,
      hideUpload,
      handleRemovePhoto,
      disabled,
    ]
  )

  const renderMultipleImgs = useCallback(() => {
    const renderImgs = []
    for (let index = 0; index < uploadedImgs.length; index++) {
      const imgData = uploadedImgs[index]
      if (index <= 4) {
        renderImgs.push(
          <DisplayFlexCCC key={imgData.filename} className="multiple-img-box">
            {uploadedImgs.length > 5 && index === 4 ? (
              <CustomText
                color={AgentColorPallette.blackGrey}
                size="0.6em"
                weight={700}
                onClick={(e) => {
                  e.stopPropagation()
                  setShowViewer({ show: true, activeIndex: 4 })
                }}
                className="viewer-btn"
              >
                {uploadedImgs.length - 4}+
              </CustomText>
            ) : (
              <div className="multiple-img-container">
                <img
                  className="multi-img"
                  src={imgData.url}
                  alt=""
                  onClick={() => handleShowViewer(index)}
                />
                <DisplayCircleIcon
                  className="img-delete-icon"
                  bgColor={AgentColorPallette.white}
                  onClick={() => handleDelete(index, name)}
                >
                  <img src={TRASH_ICON} width={12} height="auto" alt="" />
                </DisplayCircleIcon>
              </div>
            )}
          </DisplayFlexCCC>
        )
      }
    }
    return (
      <MultipleImgContainer count={uploadedImgs.length < 5 ? uploadedImgs.length : 5} error={error}>
        {renderImgs}
      </MultipleImgContainer>
    )
  }, [uploadedImgs, handleDelete, handleShowViewer, name, error])

  return (
    <UploadFileStyle className={className} error={error}>
      <Row align="center" justify="space-between" className="upload-title">
        <FormItemLabel title={title} required={required} margin="0" />
        {isMultiple && !!uploadedImgs?.length && (
          <>
            <div className="line" />
            <Row align="center" className="add-photo-btn-box">
              <img src={GOLD_UPLOAD_ICON} alt="" />
              <span className="add-photo">{LANG_STRINGS.addPhoto}</span>
              <input
                type="file"
                className="upload-file-input"
                id={name}
                name={name}
                onChange={handleUpload}
                accept={window.PPBridge ? INPUT_FILE_TYPE.IMAGE : fileType || INPUT_FILE_TYPE.IMAGE}
                multiple={isMultiple}
              />
            </Row>
          </>
        )}
      </Row>
      <div className="upload-container">
        {(GET_UPLOAD_LINK_LOADER || UPLOAD_DOC_LOADER || isImgUploading) &&
          name === that.current.currentFileUploadName && (
            <div className="upload-container-loader">
              <LoaderSvg isLoader size="24px" />
            </div>
          )}
        {!isMultiple && uploadLink && !['xlsx'].includes(getFileExtension(uploadLink)) ? (
          getImageContainer(uploadLink)
        ) : uploadedImgs.length ? (
          renderMultipleImgs()
        ) : (
          <Row align="center" justify="space-between" className="upload-file-btn-box">
            <span className="upload-btn-text">{LANG_STRINGS.upload}</span>
            <img src={UPLOAD_ICON} alt="UPLOAD_GREY" />
            <input
              type="file"
              id={name}
              name={name}
              onChange={handleUpload}
              className="upload-file-input"
              accept={window.PPBridge ? INPUT_FILE_TYPE.IMAGE : fileType || INPUT_FILE_TYPE.IMAGE}
              multiple={isMultiple}
            />
          </Row>
        )}
      </div>
      <Error>{error}</Error>
      {showGuideBtn && (
        <Row align="center" onClick={handleShowHelp} className="cursor upload-guide-box">
          <img src={MINI_HELP_ICON} alt="Help" width={12} />
          <CustomText
            color={AgentColorPallette.goldenText}
            weight={700}
            padLeft="6px"
            size="0.7em"
            bottom="0"
          >
            {LANG_STRINGS.seeGuide}
          </CustomText>
        </Row>
      )}
      {showGuide && (
        <GuideBottomSheet
          show={showGuide}
          onClose={() => setShowGuide(false)}
          guideData={guideData}
        />
      )}
      {showViewer?.show && (
        <ImageViewer
          show={showViewer.show}
          activeIndex={showViewer.activeIndex}
          onClose={() => setShowViewer({ show: false })}
          data={uploadedImgs}
          viewerImg={{
            name,
            url:
              isMultiple && uploadedImgs.length > 0
                ? uploadedImgs.map((img) => img.url)
                : uploadLink,
          }}
          onDelete={handleDelete}
          onChange={handleChangeViewer}
          showBtn={!disabled}
          fileType={fileType}
        />
      )}
    </UploadFileStyle>
  )
}

export default UploadFileContainer
