import { DASHBOARD_ACTIONS } from './actions'

export const INITIAL_STATE = {
  getOfflineAlertsData: [],
}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case DASHBOARD_ACTIONS.GET_PRODUCT:
    case DASHBOARD_ACTIONS.UPDATE_OFFLINE_ALERT:
    case DASHBOARD_ACTIONS.NOTIFICATION_DETAILS:
      return {
        ...state,
        ...payload,
      }
    case DASHBOARD_ACTIONS.GET_OFFLINE_ALERTS:
      return {
        ...state,
        getOfflineAlertsData: [
          ...state.getOfflineAlertsData,
          ...(payload.getOfflineAlertsData?.data || []),
        ],
        getOfflineAlertsMetaData: payload.getOfflineAlertsMetaData?.meta_data,
      }
    case DASHBOARD_ACTIONS.OFFLINE_QUOTE_LIST:
      return {
        ...state,
        offlineQuoteListData: [
          ...(state.offlineQuoteListData || []),
          ...(payload?.offlineQuoteListData.data || []),
        ],
        offlineQuoteListMetaData: payload?.offlineQuoteListData.meta_data,
      }
    default:
      return state
  }
}

export default reducer
