import { useState, useEffect, useCallback } from 'react'
import moment from 'moment'
import { useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import BottomSheetSelectMonths from '../../../../../components/BottomSheetSelectMonth'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { formatMoney, mapNumberToMonth } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import { useGetAgentGWP } from '../../../../../state/globalState/hooks/useGlobalContext'
import { AgentBadgeStyle } from './index.style'

function AgentBadge({ isNotificationCount, agentCode }) {
  const [showMonthModal, setShowMonthModal] = useState(false)
  const [, dispatchLoader] = useLoaderContextValue()
  const [{ getAgentGwpData = {} }, getAgentGwpRequest] = useGetAgentGWP()
  const [month, setMonth] = useState(moment().month())
  const [year, setYear] = useState(moment().year())

  useEffect(() => {
    getAgentGwpRequest({ agent_code: agentCode })
  }, [getAgentGwpRequest, agentCode])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_AGENT_BADGES_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  const handleCloseMonthModal = useCallback(() => {
    setShowMonthModal(false)
  }, [])

  return (
    <AgentBadgeStyle isNotificationCount={isNotificationCount}>
      <div className="border-top">
        <Row align="center" justify="space-between">
          <CustomText color={AgentColorPallette.darkCharcoal} size="14px" weight={800}>
            {LANG_STRINGS.gwp}
          </CustomText>
          <CustomText color={AgentColorPallette.darkCharcoal} size="14px" weight={800}>
            {LANG_STRINGS.chooseMonth}
          </CustomText>
        </Row>
        <Row align="center" justify="space-between">
          <CustomText color={AgentColorPallette.darkCharcoal} size="16px" weight={800}>
            {formatMoney(getAgentGwpData.paid_gwp, 0)}
          </CustomText>
          <CustomText
            color={AgentColorPallette.darkCharcoal}
            size="16px"
            weight={800}
            onClick={() => setShowMonthModal(true)}
          >
            {mapNumberToMonth(month, true)} {year}
            <i className="fas fa-triangle-down" />
          </CustomText>
        </Row>
      </div>
      {showMonthModal && (
        <BottomSheetSelectMonths
          show={showMonthModal}
          onClose={handleCloseMonthModal}
          month={month}
          year={year}
          setMonth={setMonth}
          setYear={setYear}
          agentGwpRequest={getAgentGwpRequest}
          agentCode={agentCode}
        />
      )}
    </AgentBadgeStyle>
  )
}

export default AgentBadge
