import { ApiContextProvider } from '@pasarpolis/common-react-hooks'
import DashboardContainer from './container'
import { DashboardContextProvider } from './context'
import { reducer as transactionReducer } from '../Policy/pages/TransactionList/state/reducer'
import { PolicyContextProvider } from '../Policy/context'

function Dashboard(props) {
  return (
    <PolicyContextProvider>
      <ApiContextProvider reducer={transactionReducer}>
        <DashboardContextProvider>
          <DashboardContainer {...props} />
        </DashboardContextProvider>
      </ApiContextProvider>
    </PolicyContextProvider>
  )
}

export default Dashboard
